// the same pattern, computed: what the flash must hold
static uint8_t uma_s7expected(uint32_t i)
{
	return S7((uint8_t)(i*37u + 11u + (i>>8)*101u));
}

uint16_t uma_s7check(void)
{
	const volatile uint8_t* flash = (const volatile uint8_t*)UMA_S7TEST_ADDRESS;
	uint16_t bad = 0;
	for(uint32_t i=0; i<UMA_S7TEST_SIZE; i++)
		if(flash[i] != uma_s7expected(i) && bad < 9999)
			bad++;
	return bad;
}
